-- READ ONLY. Split stage 001A verification. Run each numbered SELECT independently.
-- 1. Stage relations, columns and constraints.
select name,to_regclass('public.'||name) object from unnest(array['openingfit_missions','openingfit_mission_training_attempts','openingfit_mission_encounters','openingfit_mission_status_events']) name;
select table_name,column_name,data_type,udt_name,is_nullable,column_default from information_schema.columns where table_schema='public' and table_name=any(array['openingfit_missions','openingfit_mission_training_attempts','openingfit_mission_encounters','openingfit_mission_status_events']) order by 1,ordinal_position;
select c.conrelid::regclass,c.conname,c.contype,pg_get_constraintdef(c.oid) from pg_constraint c where c.conrelid=any(array['openingfit_missions','openingfit_mission_training_attempts','openingfit_mission_encounters','openingfit_mission_status_events']::regclass[]) order by 1,2;
-- 2. Indexes, RLS, policies, grants and triggers relevant to this and prior stages.
select tablename,indexname,indexdef from pg_indexes where schemaname='public' and tablename=any(array['openingfit_missions','openingfit_mission_training_attempts','openingfit_mission_encounters','openingfit_mission_status_events']) order by 1,2;
select c.relname,c.relrowsecurity from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname='public' and c.relname=any(array['openingfit_missions','openingfit_mission_training_attempts','openingfit_mission_encounters','openingfit_mission_status_events']) order by 1;
select tablename,policyname,roles,cmd,qual,with_check from pg_policies where schemaname='public' and tablename=any(array['openingfit_missions','openingfit_mission_training_attempts','openingfit_mission_encounters','openingfit_mission_status_events']) order by 1,2;
select table_name,grantee,privilege_type from information_schema.role_table_grants where table_schema='public' and table_name=any(array['openingfit_missions','openingfit_mission_training_attempts','openingfit_mission_encounters','openingfit_mission_status_events']) order by 1,2,3;
select event_object_table,trigger_name,action_timing,event_manipulation,action_statement from information_schema.triggers where event_object_schema='public' and event_object_table=any(array['openingfit_missions','openingfit_mission_training_attempts','openingfit_mission_encounters','openingfit_mission_status_events']) order by 1,2;
-- 3. Functions and execution privileges.
select p.proname,pg_get_function_identity_arguments(p.oid),p.prosecdef,p.proconfig,has_function_privilege('public',p.oid,'execute') public_execute,has_function_privilege('anon',p.oid,'execute') anon_execute,has_function_privilege('authenticated',p.oid,'execute') authenticated_execute,has_function_privilege('service_role',p.oid,'execute') service_execute from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname=any(array['openingfit_protect_mission_identity']) order by 1,2;
-- 4. Stage classification aid. Expected: four tables, 46 exact constraints and eight exact explicit indexes; stage_complete also requires no ordinary-client privileges.
with checks as (select (not exists(select 1 from pg_class r join pg_namespace n on n.oid=r.relnamespace where n.nspname='public' and r.relname=any(array['openingfit_missions','openingfit_mission_training_attempts','openingfit_mission_encounters','openingfit_mission_status_events','openingfit_missions_one_primary_active_idx','openingfit_missions_current_lookup_idx','openingfit_missions_history_idx','openingfit_missions_position_idx','openingfit_missions_source_report_idx','openingfit_mission_attempts_history_idx','openingfit_mission_encounters_verification_idx','openingfit_mission_status_events_history_idx']))) absent,((select count(*) from pg_class r join pg_namespace n on n.oid=r.relnamespace where n.nspname='public' and r.relkind='r' and r.relname=any(array['openingfit_missions','openingfit_mission_training_attempts','openingfit_mission_encounters','openingfit_mission_status_events']))=4 and not exists(select 1 from (values ('openingfit_missions','openingfit_missions_one_primary_active_idx',$idx$CREATE UNIQUE INDEX openingfit_missions_one_primary_active_idx ON public.openingfit_missions USING btree (user_id) WHERE (is_primary AND (status = ANY (ARRAY['assigned'::text, 'learning'::text, 'awaiting_evidence'::text, 'improving'::text, 'needs_review'::text])))$idx$), ('openingfit_missions','openingfit_missions_current_lookup_idx',$idx$CREATE INDEX openingfit_missions_current_lookup_idx ON public.openingfit_missions USING btree (user_id, status, updated_at DESC) WHERE is_primary$idx$), ('openingfit_missions','openingfit_missions_history_idx',$idx$CREATE INDEX openingfit_missions_history_idx ON public.openingfit_missions USING btree (user_id, created_at DESC)$idx$), ('openingfit_missions','openingfit_missions_position_idx',$idx$CREATE INDEX openingfit_missions_position_idx ON public.openingfit_missions USING btree (user_id, exact_position_key, status)$idx$), ('openingfit_missions','openingfit_missions_source_report_idx',$idx$CREATE INDEX openingfit_missions_source_report_idx ON public.openingfit_missions USING btree (user_id, source_report_id) WHERE (source_report_id IS NOT NULL)$idx$), ('openingfit_mission_training_attempts','openingfit_mission_attempts_history_idx',$idx$CREATE INDEX openingfit_mission_attempts_history_idx ON public.openingfit_mission_training_attempts USING btree (user_id, mission_id, created_at DESC)$idx$), ('openingfit_mission_encounters','openingfit_mission_encounters_verification_idx',$idx$CREATE INDEX openingfit_mission_encounters_verification_idx ON public.openingfit_mission_encounters USING btree (user_id, mission_id, qualifies_for_verification, played_at)$idx$), ('openingfit_mission_status_events','openingfit_mission_status_events_history_idx',$idx$CREATE INDEX openingfit_mission_status_events_history_idx ON public.openingfit_mission_status_events USING btree (user_id, mission_id, created_at)$idx$)) e(tablename,indexname,indexdef) left join pg_indexes a on a.schemaname='public' and a.indexname=e.indexname where a.tablename is distinct from e.tablename or a.indexdef is distinct from e.indexdef) and (select count(*)=46 and md5(string_agg(n.nspname||'.'||r.relname||'|'||c.conname||'|'||c.contype::text||'|'||pg_get_constraintdef(c.oid,false),chr(10) order by n.nspname,r.relname,c.conname))='cb93fc8e4263fd7b74d89d8fc1527d02' from pg_constraint c join pg_class r on r.oid=c.conrelid join pg_namespace n on n.oid=r.relnamespace where n.nspname='public' and r.relname=any(array['openingfit_missions','openingfit_mission_training_attempts','openingfit_mission_encounters','openingfit_mission_status_events']))) structural,((select count(*) from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname='public' and c.relname=any(array['openingfit_missions','openingfit_mission_training_attempts','openingfit_mission_encounters','openingfit_mission_status_events']) and c.relrowsecurity)=4 and not exists(select 1 from (values('openingfit_missions'),('openingfit_mission_training_attempts'),('openingfit_mission_encounters'),('openingfit_mission_status_events')) t(name) cross join (values(0::oid),('anon'::regrole::oid),('authenticated'::regrole::oid)) r(oid) cross join (values('SELECT'),('INSERT'),('UPDATE'),('DELETE'),('TRUNCATE'),('REFERENCES'),('TRIGGER')) p(name) where has_table_privilege(r.oid,to_regclass('public.'||t.name),p.name)) and not exists(select 1 from pg_policies where schemaname='public' and tablename=any(array['openingfit_missions','openingfit_mission_training_attempts','openingfit_mission_encounters','openingfit_mission_status_events'])) and not exists(select 1 from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname like '%openingfit_mission%') and not exists(select 1 from pg_trigger t where t.tgrelid=any(array[to_regclass('public.openingfit_missions'),to_regclass('public.openingfit_mission_training_attempts'),to_regclass('public.openingfit_mission_encounters'),to_regclass('public.openingfit_mission_status_events')]) and not t.tgisinternal)) contained) select case when absent then 'stage_absent' when structural and contained then 'stage_complete' when structural then 'stage_complete_but_uncontained' else 'stage_partial' end classification from checks;
